    65|// Validate date of birth: required, ISO YYYY-MM-DD, real calendar date, age 18-120
    66|function validateDateOfBirth(dateOfBirth: string): { valid: boolean; reason?: string } {
    67|  if (!dateOfBirth) return { valid: false, reason: 'Date of birth is required.' };
    68|  const match = dateOfBirth.match(/^(\d{4})-(\d{2})-(\d{2})$/);
    69|  if (!match) return { valid: false, reason: 'Date of birth must be in YYYY-MM-DD format.' };
    70|  const year = Number(match[1]);
    71|  const month = Number(match[2]);
    72|  const day = Number(match[3]);
    73|  if (month < 1 || month > 12) return { valid: false, reason: 'Please enter a valid date of birth.' };
    74|  const daysInMonth = new Date(Date.UTC(year, month, 0)).getUTCDate();
    75|  if (day < 1 || day > daysInMonth) return { valid: false, reason: 'Please enter a valid date of birth.' };
    76|  const now = new Date();
    77|  let age = now.getUTCFullYear() - year;
    78|  const hadBirthdayThisYear =
    79|    now.getUTCMonth() + 1 > month || (now.getUTCMonth() + 1 === month && now.getUTCDate() >= day);
    80|  if (!hadBirthdayThisYear) age -= 1;
    81|  if (age < 18) return { valid: false, reason: 'You must be at least 18 years old to create an account.' };
    82|  if (age > 120) return { valid: false, reason: 'Please enter a valid date of birth.' };
    83|  return { valid: true };
