   109|// POST /api/members/register
   110|export async function handleMemberRegister(request: Request): Promise<Response> {
   111|  const body = await parseBody(request);
   112|  const email = asString(body.email).toLowerCase();
   113|  const password = asString(body.password);
   114|  const firstName = asString(body.firstName);
   115|  const lastName = asString(body.lastName);
   116|  const phone = asString(body.phone);
   117|  const country = asString(body.country);
   118|  const zipCode = asString(body.zipCode);
