   120|    ? (body.roles.filter(
   121|        (r): r is MemberRoleInterest => typeof r === 'string' && VALID_ROLE_INTERESTS.has(r as MemberRoleInterest)
   122|      ))
   123|    : [];
   124|  const acceptTerms = !!body.acceptTerms;
   125|  const pictureUrl = asString(body.pictureUrl);
   126|  const dateOfBirth = asString(body.dateOfBirth);
   127|  const gender = asString(body.gender).toLowerCase();
