   133|  if (!isValidEmail(email)) {
   134|    return jsonResponse({ success: false, message: 'Please enter a valid email address.', deploymentMarker: DEPLOYMENT_MARKER }, 400);
   135|  }
   136|  const pwCheck = validatePassword(password);
   137|  if (!pwCheck.valid) {
   138|    return jsonResponse({ success: false, message: pwCheck.reason || 'Password does not meet requirements.', deploymentMarker: DEPLOYMENT_MARKER }, 400);
   139|  }
   140|  if (!phone || phone.replace(/\D/g, '').length < 10) {
   141|    return jsonResponse({ success: false, message: 'Please enter a valid phone number.', deploymentMarker: DEPLOYMENT_MARKER }, 400);
   142|  }
   143|  if (!acceptTerms) {
   144|    return jsonResponse({ success: false, message: 'You must accept the Terms of Service.', deploymentMarker: DEPLOYMENT_MARKER }, 400);
   145|  }
   146|  const dobCheck = validateDateOfBirth(dateOfBirth);
   147|  if (!dobCheck.valid) {
   148|    return jsonResponse({ success: false, message: dobCheck.reason || 'Please enter a valid date of birth.', deploymentMarker: DEPLOYMENT_MARKER }, 400);
   149|  }
   150|  const genderCheck = validateGender(gender);
   151|  if (!genderCheck.valid) {
   152|    return jsonResponse({ success: false, message: genderCheck.reason || 'Gender is required.', deploymentMarker: DEPLOYMENT_MARKER }, 400);
   153|  }
   154|  if (roles.length === 0) {
   155|    return jsonResponse({ success: false, message: 'Please select at least one role to continue.', deploymentMarker: DEPLOYMENT_MARKER }, 400);
   156|  }
   157|
   158|  const result = await registerMember({
   159|    email,
   160|    password,
   161|    firstName,
   162|    lastName,
   163|    dateOfBirth,
   164|    gender,
   165|    phone,
   166|    country,
   167|    zipCode,
   168|    roles,
   169|    acceptTerms,
   170|    pictureUrl,
   171|  });
   172|
   173|  if (result.success && result.userId) {
   174|    // Auto-send verification codes
   175|    await storeVerificationCode({ userId: result.userId, type: 'email' });
   176|    await storeVerificationCode({ userId: result.userId, type: 'phone' });
   177|
   178|    // Onboarding fanout: member profile + CRM lead + marketing profile +
   179|    // AI profile + newsletter + app account → status FREE MEMBER.
   180|    try {
   181|      await onboardNewMember({
   182|        userId: result.userId,
   183|        firstName,
   184|        lastName,
   185|        email,
   186|        phone,
   187|        country,
   188|        zipCode,
   189|        roles,
   190|        pictureUrl,
   191|      });
   192|    } catch (fanoutErr) {
   193|      console.error('[Members] Onboarding fanout failed (non-fatal):', fanoutErr);
   194|    }
   195|
   196|    // Canonical Members sync — every landing registration lands in public.members.
   197|    try {
   198|      await upsertCanonicalMember({
   199|        fullName: `${firstName} ${lastName}`.trim(),
   200|        email,
   201|        phone,
   202|        memberType: roles[0] || 'member',
   203|        source: 'landing_page',
   204|        sourceDetail: 'members/register',
   205|        investorInterest: roles.join(', '),
   206|        preferredZipcode: zipCode,
   207|        pictureUrl,
   208|        authUserId: result.userId,
   209|      });
   210|    } catch (syncErr) {
   211|      console.error('[Members] Canonical member sync failed (non-fatal):', syncErr);
   212|    }
   213|
   214|    return jsonResponse({
   215|      success: true,
   216|      message: result.message,
   217|      userId: result.userId,
   218|      email: result.email,
   219|      requiresVerification: true,
   220|      deploymentMarker: DEPLOYMENT_MARKER,
   221|    });
   222|  }
   223|
   224|  return jsonResponse(
   225|    { success: false, message: result.message, deploymentMarker: DEPLOYMENT_MARKER },
   226|    result.message.includes('already exists') ? 409 : 400
   227|  );
