  };
  var _regState = REG_STATES.IDLE;
  function setRegState(s) { _regState = s; console.log('[IVX Reg] state ->', s); }
  function regStateIsTerminal() { return _regState === REG_STATES.COMPLETED || _regState === REG_STATES.BLOCKED; }

