/**
 * IVX Registration Reliability Phase 2 — backend tests.
 *
 * Covers the normalized error contract, idempotency, partial-failure recovery,
 * and the health endpoint. These tests stub the underlying `registerMember`
 * pipeline so they run without a live Supabase connection.
 */
import { describe, it, expect, beforeEach, afterEach, mock } from 'bun:test';
import {
  orchestrateRegistration,
  checkRegistrationHealth,
  getRegistrationStatus,
  type RegistrationRequestInput,
} from './ivx-registration-orchestrator';

// --- Stub the durable store so persistence is in-memory + reversible ---
const _store: Record<string, unknown> = {};
const durableStoreModule = require('./ivx-durable-store');
let durableConfigured = true;
let originalIsConfigured: typeof durableStoreModule.isDurableStoreConfigured;
let originalRead: typeof durableStoreModule.readDurableJson;
let originalWrite: typeof durableStoreModule.writeDurableJson;

beforeEach(() => {
  for (const k of Object.keys(_store)) delete _store[k];
  originalIsConfigured = durableStoreModule.isDurableStoreConfigured;
  originalRead = durableStoreModule.readDurableJson;
  originalWrite = durableStoreModule.writeDurableJson;
  durableStoreModule.isDurableStoreConfigured = () => durableConfigured;
  durableStoreModule.readDurableJson = async <T>(file: string, fallback: T): Promise<T> => {
    return ((_store[file] as T) ?? fallback);
  };
  durableStoreModule.writeDurableJson = async (file: string, value: unknown) => {
    _store[file] = value;
  };
});

afterEach(() => {
  durableStoreModule.isDurableStoreConfigured = originalIsConfigured;
  durableStoreModule.readDurableJson = originalRead;
  durableStoreModule.writeDurableJson = originalWrite;
});

// --- Stub the member-database `registerMember` so we can simulate outcomes ---
const memberDbModule = require('./ivx-member-database');
const originalRegister = memberDbModule.registerMember;

function stubRegister(result: {
  success: boolean;
  message: string;
  userId?: string;
  email?: string;
  requiresVerification: boolean;
  deploymentMarker: string;
}) {
  memberDbModule.registerMember = async () => result;
}

afterEach(() => {
  memberDbModule.registerMember = originalRegister;
});

function validInput(overrides: Partial<RegistrationRequestInput> = {}): RegistrationRequestInput {
  return {
    email: 'test-' + Math.random().toString(36).substring(2, 8) + '@example.com',
    password: 'Sup3rSecurePassphrase!',
    firstName: 'Test',
    lastName: 'User',
    phone: '555-555-5555',
    country: 'US',
    zipCode: '10001',
    roles: ['investor'],
    acceptTerms: true,
    dateOfBirth: '1990-01-01',
    gender: 'prefer_not_to_say',
    ...overrides,
  };
}

describe('ivx-registration-orchestrator — normalized error contract', () => {
  it('rejects missing first name with INVALID_EMAIL code + traceId + stage', async () => {
    const result = await orchestrateRegistration(validInput({ firstName: '' }));
    expect(result.ok).toBe(false);
    if (!result.ok) {
      expect(result.code).toBe('INVALID_EMAIL');
      expect(result.stage).toBe('VALIDATING');
      expect(result.traceId).toMatch(/^ivx-reg-/);
      expect(result.retryable).toBe(false);
      expect(result.registrationRequestId).toBeTruthy();
    }
  });

  it('rejects weak password (<12 chars) with WEAK_PASSWORD code', async () => {
    const result = await orchestrateRegistration(validInput({ password: 'Short1!' }));
    expect(result.ok).toBe(false);
    if (!result.ok) {
      expect(result.code).toBe('WEAK_PASSWORD');
      expect(result.stage).toBe('VALIDATING');
      expect(result.message).toContain('12 characters');
    }
  });

  it('rejects unaccepted terms with a non-retryable VALIDATING error', async () => {
    const result = await orchestrateRegistration(validInput({ acceptTerms: false }));
    expect(result.ok).toBe(false);
    if (!result.ok) {
      expect(result.stage).toBe('VALIDATING');
      expect(result.retryable).toBe(false);
    }
  });

  it('accepts a 12+ character passphrase without character-class requirements', async () => {
    stubRegister({
      success: true,
      userId: 'test-user-id-1',
      email: 'passphrase@example.com',
      message: 'ok',
      requiresVerification: true,
      deploymentMarker: 'test',
    });
    const result = await orchestrateRegistration(
      validInput({ email: 'passphrase@example.com', password: 'all-lowercase-passphrase-no-symbols-but-long-enough' })
    );
    expect(result.ok).toBe(true);
  });
});

describe('ivx-registration-orchestrator — idempotency', () => {
